import React from 'react';
import { CompareFAQLogResponse } from "../../../types/adminLog";

interface FAQLogDetailFormProps {
  prev_faq: CompareFAQLogResponse["data"]["prev_faq"];
  new_faq: CompareFAQLogResponse["data"]["new_faq"];
}

const FAQLogDetailForm: React.FC<FAQLogDetailFormProps> = ({
  prev_faq,
  new_faq,
}) => {
  // 빈 객체를 넣는 대신 빈 문자열로 초기화
  const prevAnswersKo = prev_faq.answer_ko.length > 0 ? prev_faq.answer_ko : [{ answer: '', url: '', email: '', phone: '' }];
  const prevAnswersEn = prev_faq.answer_en.length > 0 ? prev_faq.answer_en : [{ answer: '', url: '', email: '', phone: '' }];
  const newAnswersKo = new_faq.answer_ko.length > 0 ? new_faq.answer_ko : [{ answer: '', url: '', email: '', phone: '' }];
  const newAnswersEn = new_faq.answer_en.length > 0 ? new_faq.answer_en : [{ answer: '', url: '', email: '', phone: '' }];

  // 이전 값과 새로운 값이 다를 때 배경색을 다르게 표시
  const getColor = (prevValue: string, newValue: string, order: number) => {
    if (prevValue !== newValue) {
      if (order === 0) {
        return prevValue === '' ? 'bg-card' : 'bg-danger-soft';
      } else if(order === 1) {
        return newValue === '' ? 'bg-card' : 'bg-success-soft';
      }
    }
    return 'bg-card';
  };
  
  return (
    <form onSubmit={(e) => e.preventDefault()} className="max-w-8xl mx-auto p-4 sm:p-8 bg-surface rounded-xl shadow-lg space-y-8">
      <h2 className="text-xl sm:text-2xl font-bold text-ink text-center">FAQ 로그 상세</h2>

      {/* 휴대폰: 기존 → 바뀐 내용을 위아래로 */}
      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-8">
        {/* Left Side: prev_faq */}
        <div className="p-4 sm:p-6 border border-line rounded-xl bg-card space-y-4">
          <h3 className="text-xl font-bold text-ink">기존 FAQ</h3>

          {/* 카테고리 및 질문 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">주요카테고리 (한글)</label>
            <input
              type="text"
              value={prev_faq.maincategory_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.maincategory_ko, new_faq.maincategory_ko, 0)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">MainCategory (English)</label>
            <input
              type="text"
              value={prev_faq.maincategory_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.maincategory_en, new_faq.maincategory_en, 0)} text-ink`}
            />
          </div>

          {/* 서브카테고리 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">하위카테고리 (한글)</label>
            <input
              type="text"
              value={prev_faq.subcategory_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.subcategory_ko, new_faq.subcategory_ko, 0)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">Subcategory (English)</label>
            <input
              type="text"
              value={prev_faq.subcategory_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.subcategory_en, new_faq.subcategory_en, 0)} text-ink`}
            />
          </div>

          {/* 질문 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">질문 (한글)</label>
            <input
              type="text"
              value={prev_faq.question_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.question_ko, new_faq.question_ko, 0)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">Question (English)</label>
            <input
              type="text"
              value={prev_faq.question_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.question_en, new_faq.question_en, 0)} text-ink`}
            />
          </div>

          {/* FAQ 답변 */}
          <div className="p-4 sm:p-6 border border-line rounded-xl bg-card space-y-4">
            <h3 className="text-xl font-bold text-ink">FAQ 답변</h3>
            {prevAnswersKo.map((answer, index) => {
              const answerEn = prevAnswersEn[index] || { answer: '', url: '', email: '', phone: '' };
              return (
                <div key={index} className="p-4 border border-line rounded-xl bg-surface space-y-2">
                  <label className="block text-lg font-medium text-ink mb-2">답변 (한글)</label>
                  <textarea
                    value={answer.answer || ''}
                    readOnly
                    className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(answer.answer, newAnswersKo[index]?.answer || '', 0)} text-ink mb-2`}
                    rows={6}
                  />
                  <label className="block text-lg font-medium text-ink mb-2">Answer (영어)</label>
                  <textarea
                    value={answerEn.answer || ''}
                    readOnly
                    className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(answerEn.answer, newAnswersEn[index]?.answer || '', 0)} text-ink mb-2`}
                    rows={6}
                  />

                  <div className="flex space-x-4">
                    <input
                      type="text"
                      value={answer.url || ''}
                      readOnly
                      placeholder='URL'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(answer.url, newAnswersKo[index]?.url || '', 0)} text-ink mb-2`}
                    />
                    <input
                      type="email"
                      value={answer.email || ''}
                      readOnly
                      placeholder='Email'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(answer.email, newAnswersKo[index]?.email || '', 0)} text-ink mb-2`}
                    />
                    <input
                      type="tel"
                      value={answer.phone || ''}
                      readOnly
                      placeholder='Phone'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(answer.phone, newAnswersKo[index]?.phone || '', 0)} text-ink mb-2`}
                    />
                  </div>
                </div>
              );
            })}
          </div>

          {/* 관리자 정보 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">관리자 이름</label>
            <input
              type="text"
              value={prev_faq.manager}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.manager, new_faq.manager, 0)} text-ink`}
            />
          </div>
        </div>

        {/* Right Side: new_faq */}
        <div className="p-4 sm:p-6 border border-line rounded-xl bg-card space-y-4">
          <h3 className="text-xl font-bold text-ink">새로운 FAQ</h3>

          {/* 카테고리 및 질문 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">주요카테고리 (한글)</label>
            <input
              type="text"
              value={new_faq.maincategory_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.maincategory_ko, new_faq.maincategory_ko, 1)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">MainCategory (English)</label>
            <input
              type="text"
              value={new_faq.maincategory_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.maincategory_en, new_faq.maincategory_en, 1)} text-ink`}
            />
          </div>

          {/* 서브카테고리 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">하위카테고리 (한글)</label>
            <input
              type="text"
              value={new_faq.subcategory_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.subcategory_ko, new_faq.subcategory_ko, 1)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">Subcategory (English)</label>
            <input
              type="text"
              value={new_faq.subcategory_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.subcategory_en, new_faq.subcategory_en, 1)} text-ink`}
            />
          </div>

          {/* 질문 필드 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">질문 (한글)</label>
            <input
              type="text"
              value={new_faq.question_ko}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.question_ko, new_faq.question_ko, 1)} text-ink`}
            />
            <label className="block text-lg font-medium text-ink mt-4 mb-2">Question (English)</label>
            <input
              type="text"
              value={new_faq.question_en}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.question_en, new_faq.question_en, 1)} text-ink`}
            />
          </div>

          {/* FAQ 답변 */}
          <div className="p-4 sm:p-6 border border-line rounded-xl bg-card space-y-4">
            <h3 className="text-xl font-bold text-ink">FAQ 답변</h3>
            {newAnswersKo.map((answer, index) => {
              const answerEn = newAnswersEn[index] || { answer: '', url: '', email: '', phone: '' };
              return (
                <div key={index} className="p-4 border border-line rounded-xl bg-surface space-y-2">
                  <label className="block text-lg font-medium text-ink mb-2">답변 (한글)</label>
                  <textarea
                    value={answer.answer || ''}
                    readOnly
                    className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prevAnswersKo[index]?.answer || '', answer.answer, 1)} text-ink mb-2`}
                    rows={6}
                  />
                  <label className="block text-lg font-medium text-ink mb-2">Answer (영어)</label>
                  <textarea
                    value={answerEn.answer || ''}
                    readOnly
                    className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prevAnswersEn[index]?.answer || '', answerEn.answer, 1)} text-ink mb-2`}
                    rows={6}
                  />
                  <div className="flex space-x-4">
                    <input
                      type="text"
                      value={answer.url || ''}
                      readOnly
                      placeholder='URL'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(prevAnswersKo[index]?.url || '', answer.url, 1)} text-ink mb-2`}
                    />
                    <input
                      type="email"
                      value={answer.email || ''}
                      readOnly
                      placeholder='Email'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(prevAnswersKo[index]?.email || '', answer.email, 1)} text-ink mb-2`}
                    />
                    <input
                      type="tel"
                      value={answer.phone || ''}
                      readOnly
                      placeholder='Phone'
                      className={`w-1/3 p-3 border border-line rounded-xl shadow-sm ${getColor(prevAnswersKo[index]?.phone || '', answer.phone, 1)} text-ink mb-2`}
                    />
                  </div>
                </div>
              );
            })}
          </div>

          {/* 관리자 정보 */}
          <div>
            <label className="block text-lg font-medium text-ink mb-2">관리자 이름</label>
            <input
              type="text"
              value={new_faq.manager}
              readOnly
              className={`w-full p-3 border border-line rounded-xl shadow-sm ${getColor(prev_faq.manager, new_faq.manager, 1)} text-ink`}
            />
          </div>
        </div>
      </div>
    </form>
  );
};

export default FAQLogDetailForm;